/**
 * Parse an Accept-Language header and return the most preferred language tag.
 * Returns "unknown" when the header is absent or contains no parseable entries.
 */
function getPreferredLanguage(acceptLanguage: string): string {
  if (!acceptLanguage.trim()) {
    return 'unknown'
  }

  const entries = acceptLanguage
    .split(',')
    .map((part) => {
      const [tag, ...params] = part.trim().split(';')
